//! The A5 boundary (`format::local_offset_at`, `format::local_offset_of_clock`) against the
//! offsets .NET gave the same zone (`rust/tests/golden/local-offset.json` under Windows,
//! `local-offset-unix.json` under Linux, regenerated by `rust/tools/local-offset-oracle`).
//! The golden zone is chosen by the zone of the machine (`tzutil /g` under Windows) or by `TZ`
//! (else `/etc/localtime`) under Linux, where every zone of the golden is also replayed in a
//! child process with its `TZ`. Only a system or a machine zone without a golden (macOS, a
//! Windows machine outside Romance Standard Time) is skipped, and said so.
//!
//! A tz offset with seconds (local mean time, before 1912, Unix only) is the named deviation of
//! PARITY.md: the port cuts it to minutes, .NET rounds it its own way.
//!
//! The skipped hour of Europe/Moscow on 2011-03-27 is the named deviation of John's decision of
//! 2026-11-16: .NET tells it by the daylight flag of its zone data, which chrono does not expose;
//! the port writes the result of its chrono rule (180 instead of 240), with no TZif reader.

/// Clock readings (zone, prefix of the reading) where the port keeps its chrono result.
const NAMED_DEVIATIONS: &[(&str, &str)] = &[("Europe/Moscow", "2011-03-27T02:")];

use std::path::Path;

use chrono::{Local, TimeZone};
use serde_json::Value;
use sermofur_core::format::{DateTimeOffset, local_offset_at, local_offset_of_clock};

/// The id .NET gives the zone of the machine (`TimeZoneInfo.Local.Id`), if it can be read.
fn zone_id() -> Option<String> {
    if cfg!(windows) {
        let out = std::process::Command::new("tzutil")
            .arg("/g")
            .output()
            .ok()?;
        return Some(String::from_utf8_lossy(&out.stdout).trim().to_owned());
    }
    if let Ok(tz) = std::env::var("TZ") {
        return Some(tz.trim_start_matches(':').to_owned());
    }
    let target = std::fs::read_link("/etc/localtime").ok()?;
    let text = target.to_string_lossy().into_owned();
    text.split("zoneinfo/").nth(1).map(str::to_owned)
}

/// Seconds of the tz offset at an instant beyond whole minutes (local mean time).
fn has_seconds(utc_ticks: i64) -> bool {
    let seconds = (utc_ticks - 621_355_968_000_000_000).div_euclid(10_000_000);
    chrono::DateTime::from_timestamp(seconds, 0).is_some_and(|utc| {
        Local
            .offset_from_utc_datetime(&utc.naive_utc())
            .local_minus_utc()
            % 60
            != 0
    })
}

#[test]
fn local_offsets_are_those_of_dotnet() {
    let name = if cfg!(windows) {
        "local-offset.json"
    } else {
        "local-offset-unix.json"
    };
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/golden")
        .join(name);
    let Ok(text) = std::fs::read_to_string(&path) else {
        eprintln!("local offsets skipped: no golden {name} for this system");
        return;
    };
    let golden: Value = serde_json::from_str(&text).expect("the golden file is valid JSON");
    // Under Unix every zone of the golden is replayed, each in a child process with its `TZ`
    // (chrono reads the zone once per process), whatever the zone of the machine.
    if cfg!(unix) && std::env::var_os("SMF_LOCAL_OFFSET_CHILD").is_none() {
        for tz in golden["zones"]
            .as_array()
            .expect("zones")
            .iter()
            .filter_map(|z| z["tz"].as_str())
        {
            let status = std::process::Command::new(std::env::current_exe().expect("this test"))
                .args([
                    "local_offsets_are_those_of_dotnet",
                    "--exact",
                    "--nocapture",
                ])
                .env("TZ", tz)
                .env("SMF_LOCAL_OFFSET_CHILD", "1")
                .status()
                .expect("the child test runs");
            assert!(status.success(), "TZ={tz}: the replay failed");
        }
    }
    let Some(id) = zone_id() else {
        eprintln!("local offsets skipped: the zone of the machine cannot be read");
        return;
    };
    let Some(zone) = golden["zones"]
        .as_array()
        .expect("zones")
        .iter()
        .find(|zone| zone["zone"] == id.as_str() || zone["tz"] == id.as_str())
    else {
        eprintln!("local offsets skipped: no golden for the zone {id}");
        return;
    };
    let mut mismatches = Vec::new();
    let mut local_mean_time = 0;
    let mut named = 0;
    for probe in zone["instants"].as_array().expect("instants") {
        let ticks = probe["utc_ticks"].as_i64().expect("ticks");
        let expected = probe["offset_minutes"].as_i64().expect("an offset");
        let offset = local_offset_at(ticks);
        if i64::from(offset) == expected {
            let text = DateTimeOffset::new(ticks, offset)
                .expect("in range")
                .to_log();
            if probe["text"] != text.as_str() {
                mismatches.push(format!(
                    "instant {ticks}: text {text}, expected {}",
                    probe["text"]
                ));
            }
        } else if has_seconds(ticks) && (i64::from(offset) - expected).abs() <= 1 {
            local_mean_time += 1;
        } else {
            mismatches.push(format!("instant {ticks}: {offset}, expected {expected}"));
        }
    }
    for probe in zone["clocks"].as_array().expect("clocks") {
        let ticks = probe["local_ticks"].as_i64().expect("ticks");
        let expected = probe["offset_minutes"].as_i64().expect("an offset");
        let offset = local_offset_of_clock(ticks);
        if i64::from(offset) == expected {
            continue;
        }
        let text = probe["text"].as_str().unwrap_or_default();
        if NAMED_DEVIATIONS
            .iter()
            .any(|(tz, prefix)| zone["tz"] == *tz && text.starts_with(prefix))
        {
            assert_eq!(offset, 180, "clock {text}: the named deviation is 180");
            named += 1;
            continue;
        }
        if has_seconds(ticks - expected * 600_000_000) && (i64::from(offset) - expected).abs() <= 1
        {
            local_mean_time += 1;
        } else {
            mismatches.push(format!(
                "clock {} ({}): {offset}, expected {expected}",
                probe["text"], probe["kind"]
            ));
        }
    }
    if zone["tz"] == "Europe/Moscow" {
        assert_eq!(named, 5, "the skipped hour of Moscow 2011 has 5 probes");
    }
    assert!(
        mismatches.is_empty(),
        "zone {id}:\n{}",
        mismatches.join("\n")
    );
    eprintln!(
        "zone {id}: {local_mean_time} probes of local mean time, {named} of the skipped hour of Moscow 2011 (named deviations)"
    );
}

#[test]
fn now_local_carries_the_offset_of_the_zone() {
    let now = DateTimeOffset::now_local();
    assert_eq!(now.offset_minutes(), local_offset_at(now.utc_ticks()));
}
